/**
 * Vector tiles in the playground (M13, ADR 0131): `?vectorStyle=<name or URL>` draws a MapLibre style from the fixture
 * tiles (`public/vector-tiles/`, generated by `e2e/vector-tiles/fixtures/generate.ts`), and `?scenario=mvt-*` sets a
 * scenario's style and view. Tests read the layer through `window.vibeglobeVectorTiles`.
 */
import type { Globe, ViewInit } from '@vibeglobe/core';
import { addVectorTiles, type VectorTileLayer } from '@vibeglobe/layers/vector-tiles';
import { createVectorTileTarget } from '@vibeglobe/renderer/vector-tiles';

/** Scenario presets: the style, the view, and the view mode. */
const SCENARIOS: Readonly<Record<string, { style: string; view?: ViewInit; mode?: '2d' | '3d' }>> = {
  'mvt-flat': { style: 'streets', view: { longitudeDeg: 9.19, latitudeDeg: 45.465, zoom: 12 }, mode: '2d' },
  'mvt-globe-zoom': { style: 'streets', view: { longitudeDeg: 9.19, latitudeDeg: 45.465, zoom: 1.5 } },
  'mvt-city': { style: 'streets', view: { longitudeDeg: 9.19, latitudeDeg: 45.465, zoom: 15, tiltDeg: 45 } },
  'mvt-labels': { style: 'streets', view: { longitudeDeg: 9.19, latitudeDeg: 45.466, zoom: 15 }, mode: '2d' },
  'mvt-terrain': { style: 'streets', view: { longitudeDeg: 6.86, latitudeDeg: 45.7, zoom: 12.5, tiltDeg: 60 } },
};

/** What tests read: the layer, once loaded, and its loading error if any. */
export interface VectorTilesHooks {
  layer: VectorTileLayer | undefined;
  error: string | undefined;
  ready: Promise<VectorTileLayer>;
}

function styleUrl(name: string): string {
  return /[/.]/.test(name) ? name : `${import.meta.env.BASE_URL}vector-tiles/styles/${name}.json`;
}

/** Shows the style the page's URL asks for, once the globe is ready. */
export async function show(globe: Globe): Promise<VectorTileLayer> {
  await globe.ready;
  return showVectorTiles(globe, new URLSearchParams(location.search));
}

/** Shows the style `params` ask for. */
export function showVectorTiles(globe: Globe, params: URLSearchParams): Promise<VectorTileLayer> {
  const scenario = SCENARIOS[params.get('scenario') ?? ''];
  const name = params.get('vectorStyle') ?? scenario?.style ?? 'streets';
  if (scenario?.mode !== undefined && !params.has('viewMode')) globe.setViewMode(scenario.mode);
  if (scenario?.view !== undefined && !params.has('zoom')) globe.jumpTo(scenario.view);
  const hooks: VectorTilesHooks = {
    layer: undefined,
    error: undefined,
    ready: addVectorTiles(globe, { style: styleUrl(name), target: createVectorTileTarget }),
  };
  hooks.ready.then(
    (layer) => (hooks.layer = layer),
    (error: unknown) => (hooks.error = String(error)),
  );
  (window as unknown as { vibeglobeVectorTiles: VectorTilesHooks }).vibeglobeVectorTiles = hooks;
  return hooks.ready;
}
